/* Lightweight QR Code Generator (Version 1-10 Byte/UTF-8 Mode) */
(function (global) {
  "use strict";

  const EXP = new Array(256);
  const LOG = new Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP[LOG[a] + LOG[b]];
  }

  function rsGeneratorPoly(ecLen) {
    let poly = [1];
    for (let i = 0; i < ecLen; i++) {
      const next = new Array(poly.length + 1).fill(0);
      const factor = EXP[i];
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], factor);
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(dataBytes, ecLen) {
    const gen = rsGeneratorPoly(ecLen);
    const msg = dataBytes.concat(new Array(ecLen).fill(0));
    for (let i = 0; i < dataBytes.length; i++) {
      const coef = msg[i];
      if (coef !== 0) {
        for (let j = 0; j < gen.length; j++) msg[i + j] ^= gfMul(gen[j], coef);
      }
    }
    return msg.slice(dataBytes.length);
  }

  const V_SPECS = {
    1: [16, 10, 1], 2: [28, 16, 1], 3: [44, 26, 1], 4: [64, 18, 2], 5: [86, 24, 2],
    6: [108, 16, 4], 7: [124, 18, 4], 8: [154, 22, 4], 9: [182, 22, 5], 10: [216, 26, 5]
  };

  function toUtf8Bytes(str) {
    return Array.from(new TextEncoder().encode(str));
  }

  function chooseVersion(byteLen) {
    for (let v = 1; v <= 10; v++) {
      const totalData = V_SPECS[v][0];
      const countBits = v < 10 ? 8 : 16;
      const neededBits = 4 + countBits + byteLen * 8;
      if (Math.ceil(neededBits / 8) <= totalData) return v;
    }
    throw new Error("Text too long for QR Code v1-10");
  }

  function buildDataCodewords(bytes, version) {
    const totalData = V_SPECS[version][0];
    const countBits = version < 10 ? 8 : 16;
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) bits.push((val >> i) & 1);
    }
    pushBits(0b0100, 4);
    pushBits(bytes.length, countBits);
    for (const b of bytes) pushBits(b, 8);
    const capacityBits = totalData * 8;
    const termLen = Math.min(4, capacityBits - bits.length);
    if (termLen > 0) pushBits(0, termLen);
    while (bits.length % 8 !== 0) bits.push(0);

    const out = [];
    for (let i = 0; i < bits.length; i += 8) {
      let byteVal = 0;
      for (let j = 0; j < 8; j++) byteVal = (byteVal << 1) | bits[i + j];
      out.push(byteVal);
    }
    const padBytes = [0xec, 0x11];
    let idx = 0;
    while (out.length < totalData) {
      out.push(padBytes[idx % 2]);
      idx++;
    }
    return out;
  }

  function interleaveAndEcc(dataCodewords, version) {
    const [totalData, ecLen, numBlocks] = V_SPECS[version];
    const shortBlockLen = Math.floor(totalData / numBlocks);
    const longBlocks = totalData % numBlocks;
    const dataBlocks = [], ecBlocks = [];
    let offset = 0;
    for (let b = 0; b < numBlocks; b++) {
      const len = shortBlockLen + (b >= numBlocks - longBlocks ? 1 : 0);
      const block = dataCodewords.slice(offset, offset + len);
      offset += len;
      dataBlocks.push(block);
      ecBlocks.push(rsEncode(block, ecLen));
    }
    const finalMsg = [];
    const maxLen = Math.max(...dataBlocks.map((b) => b.length));
    for (let i = 0; i < maxLen; i++) {
      for (const blk of dataBlocks) if (i < blk.length) finalMsg.push(blk[i]);
    }
    for (let i = 0; i < ecLen; i++) {
      for (const ec of ecBlocks) finalMsg.push(ec[i]);
    }
    return finalMsg;
  }

  const ALIGN_CENTERS = {
    2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30], 6: [6, 34],
    7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46], 10: [6, 28, 50]
  };

  function createMatrix(version) {
    const size = version * 4 + 17;
    const grid = Array.from({ length: size }, () => new Array(size).fill(null));
    const fixed = Array.from({ length: size }, () => new Array(size).fill(false));

    function setFixed(r, c, val) {
      if (r >= 0 && r < size && c >= 0 && c < size) {
        grid[r][c] = val ? 1 : 0;
        fixed[r][c] = true;
      }
    }

    function drawFinder(topR, leftC) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const rr = topR + r, cc = leftC + c;
          if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue;
          const onBorder = r === 0 || r === 6 || c === 0 || c === 6;
          const inCore = r >= 2 && r <= 4 && c >= 2 && c <= 4;
          const isSep = r === -1 || r === 7 || c === -1 || c === 7;
          setFixed(rr, cc, !isSep && (onBorder || inCore));
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    for (let i = 8; i < size - 8; i++) {
      const bit = i % 2 === 0;
      setFixed(6, i, bit);
      setFixed(i, 6, bit);
    }

    if (version >= 2) {
      const centers = ALIGN_CENTERS[version];
      for (const r of centers) {
        for (const c of centers) {
          if (fixed[r][c]) continue;
          for (let dr = -2; dr <= 2; dr++) {
            for (let dc = -2; dc <= 2; dc++) {
              setFixed(r + dr, c + dc, Math.abs(dr) === 2 || Math.abs(dc) === 2 || (dr === 0 && dc === 0));
            }
          }
        }
      }
    }

    setFixed(size - 8, 8, true);
    for (let i = 0; i < 9; i++) {
      if (!fixed[8][i]) fixed[8][i] = "fmt";
      if (!fixed[i][8]) fixed[i][8] = "fmt";
    }
    for (let i = 0; i < 8; i++) {
      if (!fixed[8][size - 1 - i]) fixed[8][size - 1 - i] = "fmt";
      if (!fixed[size - 1 - i][8]) fixed[size - 1 - i][8] = "fmt";
    }
    return { size, grid, fixed };
  }

  function placeBits(matrix, codewords) {
    const { size, grid, fixed } = matrix;
    const bitStream = [];
    for (const cw of codewords) {
      for (let i = 7; i >= 0; i--) bitStream.push((cw >> i) & 1);
    }
    let bitIdx = 0, upward = true;
    for (let col = size - 1; col > 0; col -= 2) {
      if (col === 6) col = 5;
      const rows = upward
        ? Array.from({ length: size }, (_, i) => size - 1 - i)
        : Array.from({ length: size }, (_, i) => i);
      for (const r of rows) {
        for (const c of [col, col - 1]) {
          if (fixed[r][c] === false) {
            grid[r][c] = bitIdx < bitStream.length ? bitStream[bitIdx++] : 0;
          }
        }
      }
      upward = !upward;
    }
  }

  function applyMask0(matrix) {
    const { size, grid, fixed } = matrix;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (fixed[r][c] === false && (r + c) % 2 === 0) grid[r][c] ^= 1;
      }
    }
  }

  function writeFormatMask0(matrix) {
    const { size, grid } = matrix;
    const fmt = 0x5412;
    const bits = [];
    for (let i = 14; i >= 0; i--) bits.push((fmt >> i) & 1);
    const coordsA = [
      [8, 0], [8, 1], [8, 2], [8, 3], [8, 4], [8, 5], [8, 7], [8, 8],
      [7, 8], [5, 8], [4, 8], [3, 8], [2, 8], [1, 8], [0, 8]
    ];
    coordsA.forEach(([r, c], idx) => (grid[r][c] = bits[idx]));
    const coordsB = [
      [size - 1, 8], [size - 2, 8], [size - 3, 8], [size - 4, 8],
      [size - 5, 8], [size - 6, 8], [size - 7, 8],
      [8, size - 8], [8, size - 7], [8, size - 6], [8, size - 5],
      [8, size - 4], [8, size - 3], [8, size - 2], [8, size - 1]
    ];
    coordsB.forEach(([r, c], idx) => (grid[r][c] = bits[idx]));
  }

  function QRCode(targetEl, options) {
    const text = typeof options === "string" ? options : (options && options.text) || "";
    const pxSize = (options && options.width) || 180;
    const bytes = toUtf8Bytes(text || "upi://pay");
    const version = chooseVersion(bytes.length);
    const dataCw = buildDataCodewords(bytes, version);
    const fullCw = interleaveAndEcc(dataCw, version);
    const matrix = createMatrix(version);
    placeBits(matrix, fullCw);
    applyMask0(matrix);
    writeFormatMask0(matrix);

    const quiet = 4;
    const totalModules = matrix.size + quiet * 2;
    const canvas = document.createElement("canvas");
    canvas.width = pxSize;
    canvas.height = pxSize;
    const ctx = canvas.getContext("2d");
    const scale = pxSize / totalModules;

    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, pxSize, pxSize);
    ctx.fillStyle = "#111111";

    for (let r = 0; r < matrix.size; r++) {
      for (let c = 0; c < matrix.size; c++) {
        if (matrix.grid[r][c] === 1) {
          ctx.fillRect(
            Math.round((c + quiet) * scale),
            Math.round((r + quiet) * scale),
            Math.ceil(scale),
            Math.ceil(scale)
          );
        }
      }
    }

    if (typeof targetEl === "string") targetEl = document.getElementById(targetEl);
    if (targetEl) {
      targetEl.innerHTML = "";
      targetEl.appendChild(canvas);
    }
  }

  global.QRCode = QRCode;
})(window);
